package dev.zomboid.clans;
import java.util.*;
public final class Rewards {
 static final Map<String,Object> previews=new HashMap<>();public static void clearPreviews(){previews.clear();}static Object preview(String key){return previews.computeIfAbsent(key,k->stack(k,1));}
 record Gun(String id,String ammo,int tier){}
 static Object registry(){return R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"ITEM");}
 static Object loc(String id){return R.call(R.type("net.minecraft.resources.ResourceLocation"),"parse",id);}
 static boolean installed(String id){try{return R.yes(R.call(registry(),"containsKey",loc(id)));}catch(Exception missing){return false;}}
 static Object empty(){return R.make("net.minecraft.world.item.ItemStack",R.get(R.type("net.minecraft.world.item.Items"),"AIR"),0);}
 static List<Gun> guns(){List<Gun> all=new ArrayList<>();try{Object indices=R.call(R.type("com.tacz.guns.api.TimelessAPI"),"getAllCommonGunIndex");for(Object entry:(Iterable<?>)indices){Map.Entry<?,?> e=(Map.Entry<?,?>)entry;Object index=e.getValue(),data=R.call(index,"getGunData");String type=R.call(index,"getType").toString().toLowerCase(Locale.ROOT);int tier=type.contains("pistol")?0:type.contains("smg")||type.contains("shotgun")?1:type.contains("rifle")?2:3;all.add(new Gun(e.getKey().toString(),R.call(data,"getAmmoId").toString(),tier));}List<Gun> fracture=all.stream().filter(g->g.id.contains("fracture")||g.id.contains("warborn")).toList();if(!fracture.isEmpty())return fracture;}catch(Exception missing){}return all;}
 static void add(Map<String,Integer> pool,String id,int count){if(installed(id))pool.merge(id,count,Integer::sum);}
 static void improve(ClanState.Profile p,int rarity){Map<String,Integer> pool=p.rewards;add(pool,"minecraft:golden_carrot",4+2*rarity);add(pool,"minecraft:experience_bottle",2+2*rarity);add(pool,"fracturepoint:steel_plate_level_iii",1+rarity);add(pool,"fracturepoint:propital",1+rarity);String[] helmets={"ratnik_helmet","ru_helmet","nato_helmet","beta7_helmet","beta7_nvg_helmet"},vests={"ratnik_chestplate","shturmovik_ru_chestplate","nato_shturmovik_chestplate","beta7_chestplate","killa_chestplate"};add(pool,"fracturepoint:"+helmets[rarity],1);if(rarity>=1)add(pool,"fracturepoint:"+vests[rarity],1);if(rarity>=2){add(pool,"fracturepoint:ratnik_leggings",1);add(pool,"fracturepoint:ratnik_boots",1);add(pool,"fracturepoint:ceramic_plate_level_iv",rarity);}List<Gun> all=guns();if(all.isEmpty())return;int desired=Math.min(3,rarity);List<Gun> chosen=all.stream().filter(g->g.tier==desired).toList();if(chosen.isEmpty())chosen=all;for(int n=0;n<(rarity>=4?3:rarity>=3?2:1);n++){Gun gun=chosen.get(Pve.random.nextInt(chosen.size()));pool.merge("gun@"+gun.id,1,Integer::sum);pool.merge("ammo@"+gun.ammo,32*(rarity+1),Integer::sum);}}
 public static Object stack(String key,int count){try{if(key.startsWith("gun@")){String id=key.substring(4);Object index=((Optional<?>)R.call(R.type("com.tacz.guns.api.TimelessAPI"),"getCommonGunIndex",loc(id))).orElse(null);if(index==null)return empty();Object item=R.call(registry(),"get",loc("tacz:modern_kinetic_gun")),stack=R.make("net.minecraft.world.item.ItemStack",item,1),gun=R.call(R.type("com.tacz.guns.api.item.IGun"),"getIGunOrNull",stack);if(gun==null)return empty();R.call(gun,"setGunId",stack,loc(id));R.call(gun,"setCurrentAmmoCount",stack,0);R.call(gun,"setBulletInBarrel",stack,false);Object modes=R.call(R.call(index,"getGunData"),"getFireModeSet");if(modes instanceof List<?> list&&!list.isEmpty())R.call(gun,"setFireMode",stack,list.get(0));return stack;}if(key.startsWith("ammo@")){String id=key.substring(5);Object available=R.call(R.type("com.tacz.guns.api.TimelessAPI"),"getCommonAmmoIndex",loc(id));if(available instanceof Optional<?> optional&&optional.isEmpty())return empty();Object item=R.call(registry(),"get",loc("tacz:ammo")),stack=R.make("net.minecraft.world.item.ItemStack",item,count),ammo=R.call(R.type("com.tacz.guns.api.item.IAmmo"),"getIAmmoOrNull",stack);if(ammo==null)return empty();R.call(ammo,"setAmmoId",stack,loc(id));return stack;}Object item=R.call(registry(),"get",loc(key));return item==R.get(R.type("net.minecraft.world.item.Items"),"AIR")?empty():R.make("net.minecraft.world.item.ItemStack",item,count);}catch(Exception missing){return empty();}}
 public static void icon(Object graphics,String key,int x,int y){Object stack=preview(key);if(((Number)R.call(stack,"getCount")).intValue()>0)R.call(graphics,"renderItem",stack,x,y);}
 public static String name(String key){Object stack=preview(key);if(((Number)R.call(stack,"getCount")).intValue()==0)return key+" (mod/pack ausente)";try{return R.call(R.call(stack,"getHoverName"),"getString").toString();}catch(Exception missing){return key;}}
}
